<?php
require_role(['admin','organisateur']);$base='index.php?page=events';if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$id=(int)($_POST['id']??0);$action=$_POST['action']??'save';if($action==='delete'){db()->prepare('DELETE FROM events WHERE id=?')->execute([$id]);flash('Épreuve supprimée avec ses engagements, séries et résultats.');redirect($base);} $catId=($_POST['category_id']??'')!==''?(int)$_POST['category_id']:null;$cat=category_by_id($catId);if($catId!==null&&!$cat){$catId=null;}$catName=$cat?$cat['name']:'Toutes catégories';$relaySize=max(2,min(8,(int)($_POST['relay_size']??4)));
 $data=[(int)($_POST['competition_id']??0),trim($_POST['name']??''),$_POST['stroke']??'Nage libre',(int)($_POST['distance']??0),$_POST['sex']??'Mixte',$catName,isset($_POST['relay'])?1:0,$_POST['phase']??'series',max(1,(int)($_POST['max_entries']??6)),$catId,$relaySize];
 if(!$data[0]||!$data[1]||$data[3]<25||!in_array($data[2],['Nage libre','Dos','Brasse','Papillon','4 nages','Relais'],true)||!in_array($data[4],['F','M','Mixte'],true)||!in_array($data[7],['series','finale'],true)){flash('Vérifiez les informations de l’épreuve.','error');}
 else{
  $conflict=null;
  if($id&&$catId!==null){ // les engagements / équipes déjà enregistrés doivent respecter la catégorie réservée
   $cd=db()->prepare('SELECT event_date FROM competitions WHERE id=?');$cd->execute([$data[0]]);$date=(string)$cd->fetchColumn();
   $q=db()->prepare('SELECT s.first_name,s.last_name,s.birth_date FROM entries en JOIN swimmers s ON s.id=en.swimmer_id WHERE en.event_id=? UNION SELECT s.first_name,s.last_name,s.birth_date FROM relay_members m JOIN swimmers s ON s.id=m.swimmer_id WHERE m.event_id=?');$q->execute([$id,$id]);
   foreach($q->fetchAll() as $sw){$conflict=category_error($catId,$sw['birth_date'],$date,$sw['first_name'].' '.$sw['last_name']);if($conflict)break;}
  }
  if($conflict){flash('Catégorie impossible : '.$conflict,'error');}
  elseif($id){db()->prepare('UPDATE events SET competition_id=?,name=?,stroke=?,distance=?,sex=?,category=?,relay=?,phase=?,max_entries=?,category_id=?,relay_size=? WHERE id=?')->execute([...$data,$id]);flash('Épreuve modifiée.');}
  else{db()->prepare('INSERT INTO events(competition_id,name,stroke,distance,sex,category,relay,phase,max_entries,category_id,relay_size) VALUES(?,?,?,?,?,?,?,?,?,?,?)')->execute($data);flash('Épreuve créée.');}
 }
 redirect($base);}
$edit=null;if(isset($_GET['edit'])){$q=db()->prepare('SELECT * FROM events WHERE id=?');$q->execute([(int)$_GET['edit']]);$edit=$q->fetch();}
?>
<div class="grid2"><section class="panel"><h3><?=$edit?'Modifier une épreuve':'Créer une épreuve'?></h3><form method="post"><input type="hidden" name="csrf" value="<?=e(csrf_token())?>"><input type="hidden" name="action" value="save"><input type="hidden" name="id" value="<?=e($edit['id']??'')?>"><label>Compétition</label><select name="competition_id" required><?php foreach(db()->query('SELECT id,name FROM competitions ORDER BY event_date DESC') as $c):?><option value="<?=$c['id']?>" <?=((int)($edit['competition_id']??0)===(int)$c['id'])?'selected':''?>><?=e($c['name'])?></option><?php endforeach;?></select><label>Nom de l'épreuve</label><input name="name" required value="<?=e($edit['name']??'')?>" placeholder="100 m nage libre"><label>Nage</label><select name="stroke"><?php foreach(['Nage libre','Dos','Brasse','Papillon','4 nages','Relais'] as $v):?><option <?=($edit['stroke']??'Nage libre')===$v?'selected':''?>><?=e($v)?></option><?php endforeach;?></select><label>Distance (m)</label><input type="number" name="distance" min="25" step="25" value="<?=e($edit['distance']??100)?>" required><label>Sexe</label><select name="sex"><?php foreach(['Mixte'=>'Mixte','F'=>'Féminin','M'=>'Masculin'] as $k=>$v):?><option value="<?=$k?>" <?=($edit['sex']??'Mixte')===$k?'selected':''?>><?=$v?></option><?php endforeach;?></select><label>Catégorie réservée</label><select name="category_id"><option value="">Toutes catégories</option><?php foreach(age_categories() as $c):?><option value="<?=$c['id']?>" <?=((int)($edit['category_id']??0)===(int)$c['id'])?'selected':''?>><?=e($c['name'].' ('.category_range_label($c).')')?></option><?php endforeach;?></select><label>Phase</label><select name="phase"><option value="series" <?=($edit['phase']??'series')==='series'?'selected':''?>>Séries</option><option value="finale" <?=($edit['phase']??'')==='finale'?'selected':''?>>Finale</option></select><label>Nombre max. de participants</label><input type="number" name="max_entries" value="<?=e($edit['max_entries']??6)?>" min="1"><label class="check"><input type="checkbox" name="relay" <?=!empty($edit['relay'])?'checked':''?>> Relais</label><label>Nageurs par équipe de relais</label><input type="number" name="relay_size" min="2" max="8" value="<?=e($edit['relay_size']??4)?>"><button class="btn primary"><?=$edit?'Enregistrer les modifications':'Enregistrer l’épreuve'?></button><?php if($edit):?> <a class="btn light" href="<?=$base?>">Annuler</a><?php endif;?></form></section><section class="panel"><h3>Épreuves</h3><div class="table-wrap"><table><tr><th>Épreuve</th><th>Compétition</th><th>Sexe</th><th>Catégorie</th><th>Type</th><th>Actions</th></tr><?php foreach(db()->query('SELECT e.*,c.name competition FROM events e JOIN competitions c ON c.id=e.competition_id ORDER BY c.event_date DESC,e.id') as $r):?><tr><td><?=e($r['name'])?> — <?=e($r['distance'])?> m <?=e($r['stroke'])?></td><td><?=e($r['competition'])?></td><td><?=e($r['sex'])?></td><td><?=e($r['category'])?></td><td><?=!empty($r['relay'])?'Relais '.(int)$r['relay_size'].' nag.':'Individuel'?><?=$r['phase']==='finale'?' · Finale':''?></td><td class="actions"><a class="link" href="<?=$base?>&edit=<?=$r['id']?>">Modifier</a><form class="inline" method="post" onsubmit="return confirm('Supprimer cette épreuve et toutes ses données associées ?')"><input type="hidden" name="csrf" value="<?=e(csrf_token())?>"><input type="hidden" name="action" value="delete"><input type="hidden" name="id" value="<?=$r['id']?>"><button class="link danger">Supprimer</button></form></td></tr><?php endforeach;?></table></div></section></div>